1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.testsupport.ScriptedExchangeRates;
5	import org.junit.jupiter.api.BeforeEach;
6	import org.junit.jupiter.api.DisplayName;
7	import org.junit.jupiter.api.Test;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.context.annotation.Import;
10	import org.springframework.http.MediaType;
11	
12	import static org.assertj.core.api.Assertions.assertThat;
13	
14	/**
15	 * The placement the whole locking design rests on, asserted from where it can actually be
16	 * wrong: the Exchange Rate provider itself, during a real request over a real socket.
17	 *
18	 * <p>Design decision 6 answers the classic objection to pessimistic locking — that a lock
19	 * held across a call to a third party makes every other request touching those rows wait on
20	 * somebody else's server — by putting the fetch in a phase of its own, above the transaction.
21	 * Nothing about that is visible in what a request returns. A version that fetched the rate
22	 * one line lower, inside the transaction, would convert correctly, credit correctly and
23	 * answer identically, and would be exactly the design this application claims not to have.
24	 *
25	 * <p><b>No lock held follows from no transaction open, and is not asserted separately.</b> A
26	 * pessimistic lock is taken by a query inside a transaction and released when that
27	 * transaction ends, so it cannot outlive one; a provider called with no transaction active
28	 * is a provider no row lock is waiting on. There is nothing further to observe from here —
29	 * the locks belong to a transaction that has not started.
30	 *
31	 * <p>{@code WhatARepeatOfAKeyGetsBackTest} makes the same claim one layer down, about the
32	 * port, with a stand-in resolution. That one holds the port to its contract; this one holds
33	 * the endpoint to using it as intended, which is a different mistake and the likelier of the
34	 * two.
35	 */
36	@Import(ScriptedExchangeRates.class)
37	class TheRateIsFetchedWithNoTransactionOpenTest extends TransferScenario {
38	
39		private static final long SOURCE = 1L;
40	
41		private static final long DESTINATION = 2L;
42	
43		private static final String KEY = "0d1f6c1e-6b0a-4a5f-9f1a-2c3d4e5f6a7b";
44	
45		@Autowired
46		private ScriptedExchangeRates rates;
47	
48		@BeforeEach
49		void openTwoAccountsInDifferentCurrencies() {
50			rates.forgetEverything();
51			rates.quoteAt("390");
52			openAccount(SOURCE, 1_000_00L, Currency.EUR);
53			openAccount(DESTINATION, 0L, Currency.HUF);
54		}
55	
56		@Test
57		@DisplayName("the provider is called with no transaction open, so no Account row lock waits on it")
58		void asksTheProviderBeforeAnyTransactionIsOpen() {
59			client().post().uri("/api/transfers")
60					.header("X-Idempotency-Key", KEY)
61					.contentType(MediaType.APPLICATION_JSON)
62					.body("""
63							{"fromAccountId": 1, "toAccountId": 2, "amountMinorUnits": 10050}""")
64					.exchange()
65					.expectStatus().isCreated();
66	
67			assertThat(rates.pairsAsked())
68					.as("the request has to have reached the provider for the rest to mean anything")
69					.containsExactly("EUR/HUF");
70			assertThat(rates.sawAnOpenTransaction())
71					.as("a transaction here would be one holding both Account row locks")
72					.isFalse();
73		}
74	}
