1	package hu.bankmonitor.payments.transfers;
2	
3	import hu.bankmonitor.payments.common.Currency;
4	import hu.bankmonitor.payments.transfers.checks.Check;
5	import hu.bankmonitor.testsupport.BootedApplicationTest;
6	import org.junit.jupiter.api.AfterEach;
7	import org.junit.jupiter.api.BeforeEach;
8	import org.springframework.beans.factory.annotation.Autowired;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	
11	import java.time.Instant;
12	import java.util.List;
13	import java.util.Map;
14	
15	/**
16	 * The Accounts, the reads and the cleanup every test of a Transfer's life shares — the
17	 * reservation that opens one and the Verdict that closes it.
18	 *
19	 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
20	 * test method makes every write it performs invisible to any other connection and rolls the
21	 * lot back at the end — which would leave
22	 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
23	 * thread's reservation, and every assertion in
24	 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
25	 * Every subclass needs real commits, so the price is paying for the cleanup by hand.
26	 *
27	 * <p>The tables are emptied before each method as well as after: one in-memory H2 database is
28	 * shared by every test in the suite, whichever application context booted it, and the
29	 * assertions below count rows rather than looking only at their own.
30	 *
31	 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
32	 * asserted is what reached the database — a round trip through the mapping under test would
33	 * agree with itself whatever it wrote.
34	 */
35	abstract class TransferScenario extends BootedApplicationTest {
36	
37		static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");
38	
39		@Autowired
40		TransferQuotes quotes;
41	
42		@Autowired
43		FundsReservation reservation;
44	
45		@Autowired
46		VerdictRecording verdicts;
47	
48		@Autowired
49		JdbcTemplate database;
50	
51		/**
52		 * Ledger first, then Transfers, then Accounts: each table points at the one below it.
53		 * Claims come last and in any order — no foreign key reaches an Idempotency Key, which
54		 * is the point of design decision 3 putting the claim above the work rather than beside
55		 * it.
56		 *
57		 * <p>The claims are emptied here rather than by the two subclasses that request
58		 * Transfers over HTTP, because a key left behind outlives the test that made it: it is
59		 * committed by design, so the next test to use the same key would be answered by the
60		 * previous test's claim instead of making one.
61		 */
62		@BeforeEach
63		@AfterEach
64		void emptyTheLedgerTransferAccountAndClaimTables() {
65			database.update("DELETE FROM check_ledger");
66			database.update("DELETE FROM transfers");
67			database.update("DELETE FROM accounts");
68			database.update("DELETE FROM idempotency_records");
69		}
70	
71		/**
72		 * With an explicit identifier, which the identity column accepts because it is declared
73		 * {@code generated by default}. The lock order is ascending by ID, so a test about two
74		 * Accounts needs to be able to say which of them is the lower one.
75		 */
76		void openAccount(long id, long balanceMinorUnits, Currency currency) {
77			database.update("""
78					INSERT INTO accounts (id, balance_minor_units, balance_currency,
79					                      reserved_amount_minor_units, reserved_amount_currency)
80					VALUES (?, ?, ?, 0, ?)
81					""", id, balanceMinorUnits, currency.name(), currency.name());
82		}
83	
84		/**
85		 * Reads as the sentence a Transfer is — an amount, out of one Account, into another —
86		 * which is deliberately not the order {@link ReservationRequest} declares its components
87		 * in. Three adjacent {@code long}s are swappable in silence either way; naming the two
88		 * Accounts {@code from} and {@code to} is what makes a swapped call read wrong.
89		 */
90		static ReservationRequest transferOf(long amountMinorUnits, long fromAccountId, long toAccountId) {
91			return new ReservationRequest(fromAccountId, toAccountId, amountMinorUnits, REQUESTED_AT);
92		}
93	
94		/**
95		 * Both phases of a request, in the order design decision 4 puts them: resolve what the
96		 * Transfer comes to on each side, then reserve it.
97		 *
98		 * <p>The real {@link TransferQuotes} rather than a hand-built {@link ConvertedAmounts},
99		 * so that a scenario written against two Accounts in one Currency is proved to make no
100		 * provider call — nothing in these tests serves one, and a phase two that reached for a
101		 * rate it does not need would fail here rather than pass with a stub.
102		 *
103		 * <p>What it does <em>not</em> reproduce is the transaction {@code IdempotentExecution}
104		 * opens around the second phase. Every scenario below is about what one reservation
105		 * writes, and {@code reserve} opens its own; the tests that need the two phases inside
106		 * the port are the ones that go over HTTP.
107		 */
108		Transfer reserve(ReservationRequest request) {
109			return reservation.reserve(request, quotes.convert(request));
110		}
111	
112		long balanceOf(long accountId) {
113			return minorUnitsOf("balance_minor_units", accountId);
114		}
115	
116		long reservedAmountOf(long accountId) {
117			return minorUnitsOf("reserved_amount_minor_units", accountId);
118		}
119	
120		/** What an overdraft check tests against, read back from the two columns it is derived from. */
121		long availableBalanceOf(long accountId) {
122			return balanceOf(accountId) - reservedAmountOf(accountId);
123		}
124	
125		List<Map<String, Object>> transferRows() {
126			return database.queryForList("SELECT * FROM transfers ORDER BY id");
127		}
128	
129		List<Map<String, Object>> checkLedgerRows() {
130			return database.queryForList("SELECT * FROM check_ledger ORDER BY id");
131		}
132	
133		/** The status the column holds, as the string it holds it as. */
134		String statusOf(long transferId) {
135			return database.queryForObject(
136					"SELECT status FROM transfers WHERE id = ?", String.class, transferId);
137		}
138	
139		/** How far the claim on an Idempotency Key has got, as the string the column holds it as. */
140		String claimedStatus(String idempotencyKey) {
141			return database.queryForObject(
142					"SELECT status FROM idempotency_records WHERE idempotency_key = ?",
143					String.class, idempotencyKey);
144		}
145	
146		/** How one Check has been answered for one Transfer, {@code null} while it is outstanding. */
147		String verdictOn(long transferId, Check check) {
148			return database.queryForObject(
149					"SELECT verdict FROM check_ledger WHERE transfer_id = ? AND required_check = ?",
150					String.class, transferId, check.name());
151		}
152	
153		private long minorUnitsOf(String column, long accountId) {
154			Long minorUnits = database.queryForObject(
155					"SELECT " + column + " FROM accounts WHERE id = ?", Long.class, accountId);
156			return minorUnits == null ? 0L : minorUnits;
157		}
158	}
