12	/**
13	 * Design decision 4's phase two: what a requested Transfer comes to on both sides, worked
14	 * out after the Idempotency Key is claimed and before any lock is taken.
15	 *
16	 * <p><b>Nothing here opens a transaction, and that is the whole reason this class is
17	 * separate from {@link FundsReservation}.</b> The Exchange Rate provider is somebody else's
18	 * server and it is unreliable by design; a call to it inside the transaction that holds two
19	 * Account row locks would make every other Transfer touching either Account wait on a third
20	 * party. Design decision 6 calls that placement the thing that makes pessimistic locking
21	 * affordable at all. {@code TheRateIsFetchedWithNoTransactionOpenTest} asserts it against
22	 * the running application rather than leaving it to this paragraph.
23	 *
24	 * <p>The two Currencies are read unlocked, which {@link AccountCurrencies} explains is safe
25	 * for that field and nothing else on the row. It is what lets the question <em>does this
26	 * Transfer need a rate at all</em> be asked before the provider is: a same-Currency Transfer
27	 * makes no call, so an outage at the provider cannot stop one.
28	 *
29	 * <p>The conversion is here rather than under the lock for the same reason the fetch is —
30	 * {@link CurrencyConversion} lives in {@code fx}, and the locked path is walked for
31	 * dependencies on that package precisely so a provider call cannot hide one hop down. What
32	 * phase three receives is {@link ConvertedAmounts}, which names no type from {@code fx} at
33	 * all.
34	 */
35	@Service
36	class TransferQuotes {
37	
38		private final AccountCurrencies currencies;
39	
40		private final ExchangeRateProvider rates;
41	
42		TransferQuotes(AccountCurrencies currencies, ExchangeRateProvider rates) {
43			this.currencies = currencies;
44			this.rates = rates;
45		}
46	
47		/**
48		 * Both sides of the requested Transfer, converted at a rate fetched for this request.
49		 *
50		 * <p>The Currencies come from the Accounts rather than from the request, which carries
51		 * none: a Transfer is denominated by its source Account, and
52		 * {@link CreateTransferRequest} has why letting a caller say otherwise would create a
53		 * claim the Accounts can contradict.
54		 *
55		 * @throws hu.bankmonitor.payments.accounts.UnknownAccountException if either Account ID
56		 *                                                                 has no row
57		 * @throws ConversionRoundsToZeroException if the amount is worth less than half a Minor
58		 *                                         Unit of the destination Currency
59		 * @throws hu.bankmonitor.payments.fx.ExchangeRateUnavailableException if the provider did
60		 *                                                                    not answer within
61		 *                                                                    its retry budget
62		 */
63		ConvertedAmounts convert(ReservationRequest request) {
64			TransferCurrencies pair =
65					currencies.forTransfer(request.sourceAccountId(), request.destinationAccountId());
66			Money debitedAmount = new Money(request.amountMinorUnits(), pair.source());
67			if (pair.areTheSame()) {
68				return ConvertedAmounts.unconverted(debitedAmount);
69			}
70	
71			ExchangeRate quote = rates.exchangeRateFor(pair.source(), pair.destination());
72			return switch (CurrencyConversion.convert(debitedAmount, pair.destination(), quote.rate())) {
73				case ConversionResult.Converted(Money creditedAmount) -> new ConvertedAmounts(
74						debitedAmount, creditedAmount, quote.rate(), quote.fetchedAt());
75				case ConversionResult.RoundsToZero() -> throw new ConversionRoundsToZeroException(
76						debitedAmount, pair.destination(), quote.rate());
77			};
78		}
