267			problem.setProperty("debitedAmountMinorUnits", debitedAmount.minorUnits());
268			problem.setProperty("debitedAmountCurrency", debitedAmount.currency());
269			problem.setProperty("destinationCurrency", refusal.getDestinationCurrency());
270			problem.setProperty("exchangeRate", refusal.getExchangeRate());
271			return problem;
272		}
