303		/**
304		 * The one refusal here that is a {@code 404}, and it is the same {@code 404} ticket 05
305		 * settled rather than a second meaning for the status: <em>the path names nothing</em>. The
306		 * identifier <em>is</em> the path, so an identifier no Transfer has addresses no resource.
307		 *
308		 * <p>That is what the {@code 422} above it buys. Answering an unknown Account inside a
309		 * payload with {@code 404} too would have given one status two meanings, and a client could
310		 * not have told "that URL does not exist" from "account 900 does not exist" without parsing
311		 * the URN it would then have needed anyway (design decision 14).
312		 */
313		@ExceptionHandler
314		ProblemDetail handleUnknownTransfer(UnknownTransferException refusal) {
315			ProblemDetail problem =
316					problemOf(HttpStatus.NOT_FOUND, ProblemType.NOT_FOUND, UNKNOWN_TRANSFER_DETAIL);
317			problem.setProperty("transferId", refusal.getTransferId());
318			return problem;
319		}
