321		/**
322		 * The two refusals a repeated Idempotency Key can meet. Both are {@code 409 Conflict} and
323		 * they give opposite advice, so what tells them apart is the {@code type} URN a client
324		 * branches on and the {@code Retry-After} that says whether coming back can help (design
325		 * decision 18).
326		 *
327		 * <p>{@code ResponseEntity} rather than the bare {@link ProblemDetail} the four refusals
328		 * above return, because a header is the whole point of this one and a returned
329		 * {@code ProblemDetail} carries no way to set one.
330		 */
331		@ExceptionHandler
332		ResponseEntity<ProblemDetail> handleRequestInProgress(RequestInProgressException refusal) {
333			return ResponseEntity.status(HttpStatus.CONFLICT)
334					.header(HttpHeaders.RETRY_AFTER, RETRY_AFTER_SECONDS)
335					.body(conflictOf(ProblemType.REQUEST_IN_PROGRESS, REQUEST_IN_PROGRESS_DETAIL));
336		}
