338		/**
339		 * No {@code Retry-After}, and its absence is the machine-readable half of the refusal:
340		 * two payloads under one key cannot be made to agree by waiting, so a client that
341		 * retried this would loop forever. The key itself is not echoed back for the reason the
342		 * record stores a hash rather than the payload — one caller's request must not be
343		 * readable through another caller's guess at its key.
344		 */
345		@ExceptionHandler
346		ResponseEntity<ProblemDetail> handleIdempotencyKeyReused(IdempotencyKeyReusedException refusal) {
347			return ResponseEntity.status(HttpStatus.CONFLICT)
348					.body(conflictOf(ProblemType.IDEMPOTENCY_KEY_REUSED, IDEMPOTENCY_KEY_REUSED_DETAIL));
349		}
