351		/** The status the four refusals above share, which is the only thing they share. */
352		private static ProblemDetail refusalOf(ProblemType type, String detail) {
353			return problemOf(HttpStatus.UNPROCESSABLE_ENTITY, type, detail);
354		}
355	
356		/** The status the two idempotency refusals share, which is likewise all they share. */
357		private static ProblemDetail conflictOf(ProblemType type, String detail) {
358			return problemOf(HttpStatus.CONFLICT, type, detail);
359		}
360	
361		/**
362		 * The parts every problem document here shares. {@code instance} is left unset on purpose:
363		 * the message converter fills it in from the request URI for any {@code ProblemDetail} that
364		 * does not name one, so setting it here would be a second copy of the request path to keep
365		 * right.
366		 *
367		 * <p>Every {@code detail} is written in this class rather than taken from the exception, on
368		 * {@code ProblemDocumentAdvice}'s reasoning: an exception message is written for a log, and
369		 * two of these carry {@code Money}, whose {@code toString} is a record's.
370		 */
371		private static ProblemDetail problemOf(HttpStatus status, ProblemType type, String detail) {
